function ProfileDeleteLatest({onBack,onContinue}) { return <Shell back={onBack}><Header title="Delete Account"/><View style={{alignItems:'center',marginTop:24}}><ImagePlaceholder size={72} label="DELETE ICON"/><Text style={{fontSize:16,fontWeight:'800',textAlign:'center',marginTop:24}}>Are you sure you want to delete this profile?</Text></View><View style={{backgroundColor:C.white,borderRadius:17,padding:16,marginTop:31}}><Text style={{fontSize:12,fontWeight:'800',marginBottom:12}}>Please Note:</Text><View style={{flexDirection:'row'}}><X size={17} color={C.red}/><Text style={{fontSize:12,lineHeight:18,flex:1,marginLeft:10}}>Deleting your PalGo profile does not delete your linked bank account.</Text></View><View style={{flexDirection:'row',marginTop:12}}><CheckCircle2 size={17} color={C.red}/><Text style={{fontSize:12,lineHeight:18,flex:1,marginLeft:10}}>You can create another profile whenever you return to the app.</Text></View></View><View style={{marginTop:75}}><Button title="Delete Account" onPress={onContinue}/></View></Shell>; }
function ProfileDeleteReasonLatest({onBack,onDelete}) { const [selected,setSelected]=useState('I have another errand app I prefer'); const reasons=['I have another errand app I prefer','Poor customer service','Security or privacy concerns','I no longer need the account','I created this account by mistake','High fees or charges','Limited features / missing services I need','Other']; return <Shell back={onBack}><Header title="Delete Account"/><View style={{alignItems:'center',marginTop:16}}><ImagePlaceholder size={58} label="DELETE ICON"/></View><Text style={{fontSize:14,fontWeight:'800',marginTop:23,marginBottom:15}}>What is the reason for deleting your Profile?</Text>{reasons.map(reason=><TouchableOpacity key={reason} onPress={()=>setSelected(reason)} style={{height:39,borderRadius:18,backgroundColor:C.white,marginBottom:9,paddingHorizontal:13,flexDirection:'row',alignItems:'center'}}><Text style={{fontSize:11,flex:1}}>{reason}</Text><View style={{height:16,width:16,borderRadius:8,borderWidth:1,borderColor:selected===reason?C.mint:C.ink,backgroundColor:selected===reason?C.mint:C.white}}/></TouchableOpacity>)}<View style={{marginTop:15}}><Button title="Delete Account" onPress={onDelete}/></View></Shell>; }
function ProfileDeleteSuccessLatest({onDone}) { return <Shell><View style={{alignItems:'center',marginTop:142}}><CheckCircle2 size={74} color={C.mint} fill={C.mint}/><Text style={{fontSize:25,fontWeight:'800',color:C.mint,marginTop:22}}>Profile Deleted</Text><Text style={{fontSize:12,color:C.muted,marginTop:24}}>Your profile has been deleted successfully.</Text></View><View style={{height:142}}/><Button title="Okay" onPress={onDone}/></Shell>; }
function OnboardingFlowFinal({page,onNext,onBack,onChoose}) { const titles=['Payments Are Safe.','All Runners Are Verified.','All Runners Are Tracked In Real-Time.']; const illustration=onboardingSlideImages[page-1]; const back=<TouchableOpacity style={{paddingTop:12,paddingBottom:2,flexDirection:'row',alignItems:'center',gap:3}} onPress={()=>onBack(page)}><ChevronLeft size={16} color={C.white}/><Text style={{fontSize:14,fontWeight:'700',color:C.white}}>Back</Text></TouchableOpacity>; return <AuthBackground variant="onboarding"><View style={[a.onboardContent,{paddingTop:70}]}><Logo/><View style={[a.onboardMiddle,{marginTop:82}]}><View style={[a.imagePlaceholder,{height:247,width:247,marginTop:0,marginBottom:43}]}>{illustration?<Image source={illustration} resizeMode="contain" style={a.onboardImage}/>:<Text style={a.placeholderLabel}>ONBOARDING IMAGE</Text>}</View><Text style={a.onboardTitle}>{titles[page-1]}</Text><View style={[a.dots,{marginTop:43}]}>{[1,2,3].map(n=><View key={n} style={[a.dot,n===page&&a.dotOn]}/>)}</View></View></View><View style={a.onboardFooter}>{page<3?<><TouchableOpacity style={a.pillPrimary} onPress={()=>onNext(page)}><Text style={a.pillPrimaryText}>Next</Text></TouchableOpacity>{page>1&&back}</>:<><View style={a.entryButtons}><TouchableOpacity style={[a.pillPrimary,a.pillOnboardChoice]} onPress={()=>onChoose('signup')}><Text style={a.pillPrimaryText}>Sign Up</Text></TouchableOpacity><TouchableOpacity style={[a.pillPrimary,a.pillOnboardChoice]} onPress={()=>onChoose('login')}><Text style={a.pillPrimaryText}>Login</Text></TouchableOpacity></View>{back}</>}</View></AuthBackground>; }
function RolePickerFinal({onPick,onDismiss}) { const illustration=onboardingSlideImages[2]; return <AuthBackground variant="onboarding"><View style={[a.onboardContent,{paddingTop:70}]}><Logo/><View style={[a.onboardMiddle,{marginTop:82}]}><View style={[a.imagePlaceholder,{height:247,width:247,marginTop:0,marginBottom:43}]}>{illustration?<Image source={illustration} resizeMode="contain" style={a.onboardImage}/>:<Text style={a.placeholderLabel}>ONBOARDING IMAGE</Text>}</View><Text style={a.onboardTitle}>All Runners Are Tracked In Real-Time.</Text><View style={[a.dots,{marginTop:43}]}>{[1,2,3].map(n=><View key={n} style={[a.dot,n===3&&a.dotOn]}/>)}</View></View></View><View style={a.dimLayer}/><View style={a.roleSheet}><TouchableOpacity onPress={onDismiss} style={a.close}><X size={17} color={C.muted}/></TouchableOpacity><TouchableOpacity style={a.pillPrimary} onPress={()=>onPick('user')}><Text style={a.pillPrimaryText}>User</Text></TouchableOpacity><TouchableOpacity style={[a.pillPrimary,{marginTop:16}]} onPress={()=>onPick('pal')}><Text style={a.pillPrimaryText}>Pal</Text></TouchableOpacity></View></AuthBackground>; }
function PalHomeFinal({errand,onErrands,onTrack,onNotify,onWallet}) { const [expanded,setExpanded]=useState(false); const active=errand||{title:'Help me buy food',location:'Lekki Phase 1',fee:2500}; const card=(item,available=false)=><TouchableOpacity onPress={available?onErrands:onTrack} style={{backgroundColor:C.white,borderRadius:18,padding:14,marginTop:10}}><Text style={{fontSize:14,fontWeight:'800'}}>{item.title}</Text><Text style={{fontSize:12,color:C.muted,marginTop:5}}>{item.location} · {money(item.fee)}</Text><Text style={{fontSize:11,color:available?C.blue:C.mint,fontWeight:'700',marginTop:8}}>{available?'View available errand':'On my way'}</Text></TouchableOpacity>; return <View style={s.homeScreen}><HomeMap/><View style={[s.homeTop,{top:42}]}><HomeActionImage source={homeActionImages.profile} label="PROFILE" Icon={UserRound} onPress={onWallet}/><HomeActionImage source={homeActionImages.notifications} label="ALERT" Icon={Bell} onPress={onNotify}/></View><View style={[s.homePanel,{bottom:75,minHeight:expanded?420:210,shadowColor:'#38466A',shadowOpacity:.23,shadowRadius:16,shadowOffset:{width:0,height:-5},elevation:12}]}><TouchableOpacity style={s.panelHandle} onPress={()=>setExpanded(v=>!v)}><View style={s.handle}/></TouchableOpacity><Text style={{fontSize:17,fontWeight:'800'}}>Active errand</Text>{card(active)}{expanded&&<><Text style={{fontSize:17,fontWeight:'800',marginTop:22}}>Available errands</Text>{card({title:'Grocery shopping',location:'Ikeja',fee:3000},true)}{card({title:'Pick up a parcel',location:'Lekki',fee:2200},true)}</>}</View></View>; }
