function PalDetailFinal({errand,onBack,onAccept,onCounter}) { return <Shell back={onBack}><Text style={{fontSize:23,fontWeight:'800',color:'#53545B',marginBottom:22}}>Errand details</Text><View style={{backgroundColor:C.white,borderRadius:18,padding:17}}><Text style={{fontSize:17,fontWeight:'800'}}>{errand.title}</Text><Text style={{fontSize:14,lineHeight:22,marginTop:15}}>{errand.description||'Please help with this errand.'}</Text><View style={{height:1,backgroundColor:C.line,marginVertical:17}}/><DetailRow Icon={MapPinned} label={errand.location}/><DetailRow Icon={Clock3} label={errand.schedule}/><DetailRow Icon={Banknote} label={`User offer: ${money(errand.fee)}`}/><Text style={{fontSize:14,color:C.muted,marginTop:7}}>Special notes</Text><Text style={{fontSize:13,lineHeight:20,marginTop:7}}>Please contact me before starting the errand.</Text></View><View style={{flexDirection:'row',gap:16,marginTop:31}}><View style={{flex:1}}><Button kind="outline" title="Counter offer" onPress={onCounter}/></View><View style={{flex:1}}><Button title="Accept" onPress={onAccept}/></View></View></Shell>; }
function CounterOffer({errand,onBack,onSend}) { const [offer,setOffer]=useState(String(errand.fee||2500)); return <Shell back={onBack}><Header title="Counter offer" sub="Set a service fee that works for this errand."/><View style={{backgroundColor:C.white,borderRadius:18,padding:17,marginBottom:24}}><Text style={{fontSize:13,color:C.muted}}>User's offer</Text><Text style={{fontSize:25,fontWeight:'800',color:C.blue,marginTop:7}}>{money(errand.fee)}</Text></View><Input label="Your counter offer" value={offer} onChangeText={v=>setOffer(v.replace(/[^0-9]/g,''))} keyboardType="numeric" placeholder="Enter amount"/><Button title="Send counter offer" onPress={()=>onSend(Number(offer)||errand.fee)}/></Shell>; }
function PaymentPending({onBack,onConfirm}) { return <View style={s.safe}><View style={{flex:1,backgroundColor:'rgba(12,19,38,.48)',justifyContent:'center',paddingHorizontal:44}}><View style={{backgroundColor:C.white,borderRadius:23,borderWidth:1,borderColor:C.blue,padding:24}}><View style={{flexDirection:'row',alignItems:'center'}}><Clock3 size={21} color={C.mint}/><Text style={{fontSize:18,fontWeight:'800',marginLeft:10}}>Payment Pending</Text></View><Text style={{fontSize:16,lineHeight:28,marginTop:43}}>We are waiting for your Pal to confirm they have received your payment.</Text><Text style={{fontSize:14,lineHeight:22,color:C.muted,marginTop:20}}>This confirmation protects both the User and the Pal.</Text><View style={{height:34}}/><Button title="I Paid Through App" onPress={onConfirm}/><TouchableOpacity onPress={onBack}><Text style={{color:C.red,textAlign:'center',fontSize:12,textDecorationLine:'underline',marginTop:20}}>Report Issue</Text></TouchableOpacity></View></View></View>; }
